css:
.ps-attribution-badge { display: inline-flex; flex-direction: column; align-items: flex-start; padding: var(--ps-space-2, 4px) var(--ps-space-3, 8px); border: 1px solid var(--ps-border-subtle); border-radius: var(--ps-corner-1, 2px); background: var(--ps-surface-base); text-decoration: none; line-height: 1.15; }
.ps-attribution-badge__label { font-size: 0.625rem; text-transform: uppercase; letter-spacing: 0.04em; color: var(--ps-ink-disabled); }
.ps-attribution-badge__name { font-size: 0.8125rem; font-weight: 600; color: var(--ps-ink-secondary); }
